// Solve solves an alphametics puzzle of the form "WORD1 + WORD2 + ... == RESULT".
// It returns a mapping from each letter to a distinct digit such that the
// equation holds, or an error if no such mapping exists.
func Solve(puzzle string) (map[string]int, error) {
	addends, result, err := parse(puzzle)
	if err != nil {
		return nil, err
	}

	// Collect the distinct letters.
	letterSet := map[rune]bool{}
	leading := map[rune]bool{}
	for _, word := range append(append([]string{}, addends...), result) {
		runes := []rune(word)
		for _, r := range runes {
			letterSet[r] = true
		}
		if len(runes) > 1 {
			leading[runes[0]] = true
		}
	}
	if len(letterSet) > 10 {
		return nil, fmt.Errorf("puzzle has %d distinct letters, at most 10 allowed", len(letterSet))
	}
	...
}
```

